import React, { useState, useEffect } from 'react';
import './App.css';

// 定义类型
interface SkillAsset {
  tokenId: number;
  name: string;
  description: string;
  owner: string;
  category: string;
  version: string;
  isExtensible: boolean;
  allowedShare: number;
  price: number;
  rentalType: 'TimesBased' | 'DurationBased' | 'SceneBased';
}

interface RentalInfo {
  tokenId: number;
  user: string;
  remainingTimes: number;
  expiryTime: number;
  rentalType: 'TimesBased' | 'DurationBased';
}

interface ActivePermissions {
  [tokenId: number]: RentalInfo;
}

interface RevenueShare {
  total: number;
  owner: number;
  platform: number;
  scene: number;
  parent: number;
}

// 模拟链上数据
const MOCK_SKILLS: SkillAsset[] = [
  {
    tokenId: 1,
    name: '天气查询',
    description: '查询当前天气和未来7天天气预报',
    owner: '0x1234...5678',
    category: 'weather',
    version: '1.0.0',
    isExtensible: false,
    allowedShare: 1000,
    price: 0.001,
    rentalType: 'TimesBased',
  },
  {
    tokenId: 2,
    name: '飞书文档读取',
    description: '读取和操作飞书文档',
    owner: '0x1234...5678',
    category: 'doc',
    version: '2.1.0',
    isExtensible: true,
    allowedShare: 500,
    price: 0.005,
    rentalType: 'TimesBased',
  },
  {
    tokenId: 3,
    name: '图像生成',
    description: '根据文本描述生成高质量图像',
    owner: '0xabcd...efgh',
    category: 'image',
    version: '1.0.0',
    isExtensible: true,
    allowedShare: 800,
    price: 0.002,
    rentalType: 'SceneBased',
  },
];

const MOCK_ACTIVE_PERMISSIONS: ActivePermissions = {
  1: {
    tokenId: 1,
    user: '0xuser...1234',
    remainingTimes: 5,
    expiryTime: Date.now() + 7 * 24 * 60 * 60 * 1000,
    rentalType: 'TimesBased',
  },
};

const MOCK_REVENUE: RevenueShare = {
  total: 0.015,
  owner: 0.010,
  platform: 0.002,
  scene: 0.003,
  parent: 0,
};

function App() {
  const [activeTab, setActiveTab] = useState<'market' | 'my-skills' | 'dashboard'>('market');
  const [selectedSkill, setSelectedSkill] = useState<SkillAsset | null>(null);
  const [rentAmount, setRentAmount] = useState<number>(1);
  const [activePermissions, setActivePermissions] = useState<ActivePermissions>(MOCK_ACTIVE_PERMISSIONS);
  const [revenueData, setRevenueData] = useState<RevenueShare>(MOCK_REVENUE);

  const handleRentSkill = (skill: SkillAsset) => {
    const newPermissions = {
      ...activePermissions,
      [skill.tokenId]: {
        tokenId: skill.tokenId,
        user: '0xuser...1234',
        remainingTimes: rentAmount,
        expiryTime: Date.now() + 7 * 24 * 60 * 60 * 1000,
        rentalType: skill.rentalType,
      },
    };
    setActivePermissions(newPermissions);

    // 更新收入数据
    const newRevenue = {
      ...revenueData,
      total: revenueData.total + skill.price * rentAmount,
      owner: revenueData.owner + skill.price * rentAmount * 0.7,
      platform: revenueData.platform + skill.price * rentAmount * 0.1,
      scene: revenueData.scene + skill.price * rentAmount * 0.2,
    };
    setRevenueData(newRevenue);
  };

  const handleExecuteSkill = (tokenId: number) => {
    const permissions = activePermissions[tokenId];
    if (!permissions || permissions.remainingTimes <= 0) {
      alert('请先租用该 Skill！');
      return;
    }

    const newPermissions = {
      ...activePermissions,
      [tokenId]: {
        ...permissions,
        remainingTimes: permissions.remainingTimes - 1,
      },
    };
    setActivePermissions(newPermissions);

    // 触发分润
    const skill = MOCK_SKILLS.find(s => s.tokenId === tokenId);
    if (skill) {
      const newRevenue = {
        ...revenueData,
        total: revenueData.total + skill.price,
        owner: revenueData.owner + skill.price * 0.7,
        platform: revenueData.platform + skill.price * 0.1,
        scene: revenueData.scene + skill.price * 0.2,
      };
      setRevenueData(newRevenue);
    }
  };

  return (
    <div className="app">
      <header className="header">
        <h1>EchoAgent</h1>
        <p>基于 ECHO 协议的 AI Agent 能力资产化平台</p>
        <div className="badge">v0.2</div>
      </header>

      <nav className="nav">
        <button
          className={`nav-item ${activeTab === 'market' ? 'active' : ''}`}
          onClick={() => setActiveTab('market')}
        >
          🛒 Skill 市场
        </button>
        <button
          className={`nav-item ${activeTab === 'my-skills' ? 'active' : ''}`}
          onClick={() => setActiveTab('my-skills')}
        >
          🔑 我的租用
        </button>
        <button
          className={`nav-item ${activeTab === 'dashboard' ? 'active' : ''}`}
          onClick={() => setActiveTab('dashboard')}
        >
          📊 收益仪表盘
        </button>
      </nav>

      <main className="main">
        {activeTab === 'market' && (
          <div className="market">
            <h2>Skill 市场</h2>
            <div className="skill-grid">
              {MOCK_SKILLS.map((skill) => (
                <div
                  key={skill.tokenId}
                  className={`skill-card ${selectedSkill?.tokenId === skill.tokenId ? 'selected' : ''}`}
                  onClick={() => setSelectedSkill(skill)}
                >
                  <div className="skill-header">
                    <h3>{skill.name}</h3>
                    <span className="category-badge">{skill.category}</span>
                  </div>
                  <p className="skill-description">{skill.description}</p>
                  <div className="skill-meta">
                    <span>Owner: {skill.owner}</span>
                    <span>Version: {skill.version}</span>
                  </div>
                  <div className="skill-footer">
                    <div className="price">
                      <span className="price-label">价格:</span>
                      <span className="price-value">{skill.price} ETH</span>
                    </div>
                    <button
                      className="rent-button"
                      onClick={(e) => {
                        e.stopPropagation();
                        setSelectedSkill(skill);
                      }}
                    >
                      租用
                    </button>
                  </div>
                </div>
              ))}
            </div>

            {selectedSkill && (
              <div className="rent-modal">
                <div className="modal-content">
                  <h3>租用 {selectedSkill.name}</h3>
                  <div className="rent-info">
                    <p>价格: {selectedSkill.price} ETH/次</p>
                    <p>分类: {selectedSkill.category}</p>
                    <p>版本: {selectedSkill.version}</p>
                    <p>可衍生: {selectedSkill.isExtensible ? '✅ 是' : '❌ 否'}</p>
                    <label>
                      租用次数:
                      <input
                        type="number"
                        min="1"
                        value={rentAmount}
                        onChange={(e) => setRentAmount(Number(e.target.value))}
                      />
                    </label>
                  </div>
                  <div className="modal-actions">
                    <button
                      className="cancel-button"
                      onClick={() => setSelectedSkill(null)}
                    >
                      取消
                    </button>
                    <button
                      className="confirm-button"
                      onClick={() => {
                        if (rentAmount > 0) {
                          handleRentSkill(selectedSkill);
                          setSelectedSkill(null);
                        }
                      }}
                    >
                      确认租用
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'my-skills' && (
          <div className="my-skills">
            <h2>我的租用</h2>
            <div className="permissions-list">
              {Object.values(activePermissions).map((permission) => {
                const skill = MOCK_SKILLS.find((s) => s.tokenId === permission.tokenId);
                if (!skill) return null;

                return (
                  <div key={permission.tokenId} className="permission-card">
                    <div className="permission-header">
                      <h3>{skill.name}</h3>
                      <span className="status-badge">✅ 已授权</span>
                    </div>
                    <div className="permission-details">
                      <p>剩余次数: {permission.remainingTimes}</p>
                      <p>类型: {permission.rentalType}</p>
                      <p>到期时间: {new Date(permission.expiryTime).toLocaleString()}</p>
                    </div>
                    <button
                      className="execute-button"
                      onClick={() => handleExecuteSkill(permission.tokenId)}
                    >
                      执行 Skill
                    </button>
                  </div>
                );
              })}
              {Object.keys(activePermissions).length === 0 && (
                <div className="empty-state">
                  <p>暂无租用的 Skills</p>
                  <button onClick={() => setActiveTab('market')}>去市场租用</button>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="dashboard">
            <h2>收益仪表盘</h2>
            <div className="revenue-summary">
              <div className="revenue-card total">
                <h4>总收入</h4>
                <p className="revenue-value">{revenueData.total.toFixed(4)} ETH</p>
              </div>
              <div className="revenue-card owner">
                <h4>Owner 收益</h4>
                <p className="revenue-value">{revenueData.owner.toFixed(4)} ETH</p>
              </div>
              <div className="revenue-card platform">
                <h4>平台收益</h4>
                <p className="revenue-value">{revenueData.platform.toFixed(4)} ETH</p>
              </div>
              <div className="revenue-card scene">
                <h4>场景分润</h4>
                <p className="revenue-value">{revenueData.scene.toFixed(4)} ETH</p>
              </div>
            </div>

            <div className="revenue-chart">
              <h4>分润明细</h4>
              <div className="chart-container">
                <div
                  className="chart-bar owner"
                  style={{ width: `${(revenueData.owner / revenueData.total) * 100}%` }}
                >
                  <span>Owner: {Math.round((revenueData.owner / revenueData.total) * 100)}%</span>
                </div>
                <div
                  className="chart-bar platform"
                  style={{ width: `${(revenueData.platform / revenueData.total) * 100}%` }}
                >
                  <span>Platform: {Math.round((revenueData.platform / revenueData.total) * 100)}%</span>
                </div>
                <div
                  className="chart-bar scene"
                  style={{ width: `${(revenueData.scene / revenueData.total) * 100}%` }}
                >
                  <span>Scene: {Math.round((revenueData.scene / revenueData.total) * 100)}%</span>
                </div>
              </div>
            </div>

            <div className="skill-stats">
              <h4>Skill 统计</h4>
              <div className="stats-grid">
                <div className="stat-item">
                  <p className="stat-value">{MOCK_SKILLS.length}</p>
                  <p className="stat-label">总 Skill 数</p>
                </div>
                <div className="stat-item">
                  <p className="stat-value">{Object.keys(activePermissions).length}</p>
                  <p className="stat-label">已租用数</p>
                </div>
                <div className="stat-item">
                  <p className="stat-value">{Object.values(activePermissions).reduce((acc, p) => acc + p.remainingTimes, 0)}</p>
                  <p className="stat-label">总使用次数</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="footer">
        <p>EchoAgent · 基于 ECHO 协议构建</p>
        <p>OpenClaw Agent 能力资产化平台</p>
      </footer>
    </div>
  );
}

export default App;

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%);
  color: #f8fafc;
  min-height: 100vh;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Header */
.header {
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  padding: 40px 20px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.header::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.1) 0%, transparent 50%);
  animation: rotate 20s linear infinite;
}

@keyframes rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.header h1 {
  font-size: 48px;
  font-weight: 800;
  margin-bottom: 8px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
}

.header p {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.9);
  margin-bottom: 16px;
}

.badge {
  display: inline-block;
  padding: 8px 16px;
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
}

/* Navigation */
.nav {
  display: flex;
  justify-content: center;
  gap: 16px;
  padding: 20px;
  background: rgba(30, 41, 59, 0.8);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(99, 102, 241, 0.2);
}

.nav-item {
  padding: 12px 24px;
  background: transparent;
  border: 2px solid transparent;
  border-radius: 8px;
  color: #94a3b8;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.nav-item:hover {
  color: #fff;
  background: rgba(99, 102, 241, 0.1);
}

.nav-item.active {
  background: rgba(99, 102, 241, 0.2);
  border-color: #6366f1;
  color: #fff;
}

/* Main Content */
.main {
  flex: 1;
  padding: 40px 20px;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

h2 {
  font-size: 32px;
  font-weight: 700;
  margin-bottom: 24px;
  text-align: center;
  background: linear-gradient(135deg, #6366f1, #22d3ee);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Market */
.market {
  padding: 20px;
}

.skill-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
  margin-bottom: 40px;
}

.skill-card {
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(99, 102, 241, 0.2);
  border-radius: 16px;
  padding: 24px;
  cursor: pointer;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.skill-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #6366f1, #22d3ee);
  transform: scaleX(0);
  transition: transform 0.3s ease;
}

.skill-card:hover {
  transform: translateY(-4px);
  border-color: rgba(99, 102, 241, 0.5);
  box-shadow: 0 20px 40px rgba(99, 102, 241, 0.2);
}

.skill-card:hover::before {
  transform: scaleX(1);
}

.skill-card.selected {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.3);
}

.skill-card.selected::before {
  transform: scaleX(1);
}

.skill-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 12px;
}

.skill-header h3 {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
}

.category-badge {
  padding: 4px 12px;
  background: rgba(34, 211, 238, 0.2);
  border: 1px solid rgba(34, 211, 238, 0.4);
  border-radius: 12px;
  font-size: 12px;
  font-weight: 600;
  color: #22d3ee;
}

.skill-description {
  color: #94a3b8;
  font-size: 14px;
  line-height: 1.6;
  margin-bottom: 16px;
  min-height: 42px;
}

.skill-meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: #64748b;
  margin-bottom: 16px;
}

.skill-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 16px;
  border-top: 1px solid rgba(99, 102, 241, 0.2);
}

.price {
  display: flex;
  align-items: center;
  gap: 8px;
}

.price-label {
  font-size: 12px;
  color: #94a3b8;
}

.price-value {
  font-size: 18px;
  font-weight: 700;
  color: #22d3ee;
}

.rent-button {
  padding: 8px 20px;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  border: none;
  border-radius: 8px;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.rent-button:hover {
  transform: scale(1.05);
  box-shadow: 0 10px 20px rgba(99, 102, 241, 0.3);
}

/* Rent Modal */
.rent-modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.8);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
}

.modal-content {
  background: rgba(30, 41, 59, 0.95);
  border: 1px solid rgba(99, 102, 241, 0.3);
  border-radius: 16px;
  padding: 32px;
  max-width: 500px;
  width: 90%;
  animation: slideIn 0.3s ease;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.modal-content h3 {
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 24px;
  color: #fff;
}

.rent-info {
  margin-bottom: 24px;
}

.rent-info p {
  color: #94a3b8;
  margin-bottom: 8px;
  font-size: 14px;
}

.rent-info label {
  display: block;
  margin-top: 16px;
  margin-bottom: 8px;
  color: #94a3b8;
  font-size: 14px;
}

.rent-info input {
  width: 100%;
  padding: 12px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid rgba(99, 102, 241, 0.3);
  border-radius: 8px;
  color: #fff;
  font-size: 16px;
}

.rent-info input:focus {
  outline: none;
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.cancel-button,
.confirm-button {
  padding: 12px 24px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.cancel-button {
  background: rgba(99, 102, 241, 0.2);
  border: 1px solid rgba(99, 102, 241, 0.3);
  color: #fff;
}

.cancel-button:hover {
  background: rgba(99, 102, 241, 0.3);
}

.confirm-button {
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  border: none;
  color: #fff;
}

.confirm-button:hover {
  transform: scale(1.05);
  box-shadow: 0 10px 20px rgba(99, 102, 241, 0.3);
}

/* My Skills */
.my-skills {
  padding: 20px;
}

.permissions-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.permission-card {
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(99, 102, 241, 0.2);
  border-radius: 16px;
  padding: 24px;
}

.permission-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.permission-header h3 {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
}

.status-badge {
  padding: 4px 12px;
  background: rgba(34, 197, 94, 0.2);
  border: 1px solid rgba(34, 197, 94, 0.4);
  border-radius: 12px;
  font-size: 12px;
  font-weight: 600;
  color: #22c55e;
}

.permission-details {
  margin-bottom: 16px;
}

.permission-details p {
  color: #94a3b8;
  margin-bottom: 8px;
  font-size: 14px;
}

.execute-button {
  width: 100%;
  padding: 12px;
  background: linear-gradient(135deg, #22d3ee, #06b6d4);
  border: none;
  border-radius: 8px;
  color: #0f172a;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.execute-button:hover {
  transform: scale(1.02);
  box-shadow: 0 10px 20px rgba(34, 211, 238, 0.3);
}

.execute-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.empty-state {
  text-align: center;
  padding: 60px 20px;
  color: #94a3b8;
}

.empty-state p {
  font-size: 18px;
  margin-bottom: 16px;
}

.empty-state button {
  padding: 12px 24px;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  border: none;
  border-radius: 8px;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.empty-state button:hover {
  transform: scale(1.05);
}

/* Dashboard */
.dashboard {
  padding: 20px;
}

.revenue-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 32px;
}

.revenue-card {
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(99, 102, 241, 0.2);
  border-radius: 16px;
  padding: 24px;
  text-align: center;
}

.revenue-card h4 {
  font-size: 14px;
  color: #94a3b8;
  margin-bottom: 12px;
  font-weight: 600;
}

.revenue-value {
  font-size: 28px;
  font-weight: 700;
  background: linear-gradient(135deg, #6366f1, #22d3ee);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.revenue-chart {
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(99, 102, 241, 0.2);
  border-radius: 16px;
  padding: 24px;
  margin-bottom: 32px;
}

.revenue-chart h4 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: #fff;
}

.chart-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.chart-bar {
  height: 40px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 600;
  color: #fff;
  transition: all 0.3s ease;
}

.chart-bar:hover {
  transform: scaleX(1.02);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
}

.chart-bar.owner {
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
}

.chart-bar.platform {
  background: linear-gradient(90deg, #22d3ee, #06b6d4);
}

.chart-bar.scene {
  background: linear-gradient(90deg, #f59e0b, #fbbf24);
}

.skill-stats {
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(99, 102, 241, 0.2);
  border-radius: 16px;
  padding: 24px;
}

.skill-stats h4 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: #fff;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 16px;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: 36px;
  font-weight: 700;
  background: linear-gradient(135deg, #6366f1, #22d3ee);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 14px;
  color: #94a3b8;
}

/* Footer */
.footer {
  text-align: center;
  padding: 40px 20px;
  color: #64748b;
  border-top: 1px solid rgba(99, 102, 241, 0.2);
  margin-top: auto;
}

.footer p {
  margin-bottom: 8px;
}

/* Responsive */
@media (max-width: 768px) {
  .header h1 {
    font-size: 32px;
  }

  .header p {
    font-size: 16px;
  }

  .nav {
    flex-direction: column;
    gap: 8px;
  }

  .nav-item {
    width: 100%;
    text-align: center;
  }

  .skill-grid {
    grid-template-columns: 1fr;
  }

  .revenue-summary {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .modal-content {
    padding: 24px;
  }

  .modal-content h3 {
    font-size: 20px;
  }
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
